import{_ as a,o as r,c as t,a2 as c}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"中断与异常","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/interrupts.md","filePath":"zh/arch/interrupts.md"}'),o={name:"zh/arch/interrupts.md"};function d(i,e,h,s,l,n){return r(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="中断与异常" tabindex="-1">中断与异常 <a class="header-anchor" href="#中断与异常" aria-label="Permalink to &quot;中断与异常&quot;">​</a></h1><h2 id="表格" tabindex="-1">表格 <a class="header-anchor" href="#表格" aria-label="Permalink to &quot;表格&quot;">​</a></h2><p><code>kernel/arch/x86_64/arch_idt.{c,h}</code>：一个包含 256 个中断门的中断描述符表（IDT）；一个新的包含 TSS 的全局描述符表（GDT）；IST1 = 恐慌栈（#DF/#MC 有自己的栈 - IST2 永远不会发生上下文切换，IST2 是专用的异常退出栈，BUG-0139）；IST2 = 调试栈。</p><h2 id="pic-和-lapic" tabindex="-1">PIC 和 LAPIC <a class="header-anchor" href="#pic-和-lapic" aria-label="Permalink to &quot;PIC 和 LAPIC&quot;">​</a></h2><p><code>arch_irq.c</code> 将 8259 重新映射到向量 32-47（IRQ0-15）。本地 APIC 的实现在 <code>arch_lapic.c</code> 中。IRQ 线路可通过 <code>irqabitest</code> 在客户机内可见。</p><h2 id="异常路径" tabindex="-1">异常路径 <a class="header-anchor" href="#异常路径" aria-label="Permalink to &quot;异常路径&quot;">​</a></h2><p>存根（<code>arch_idt_stub.S</code>）构建一个帧，并通过向量进行分发：缺页异常增长（栈/堆）、系统调用入口（int 0x80 系列 -&gt; <code>core_syscall.c</code>）、设备 IRQ，以及任何未处理情况的崩溃路径：寄存器转储到串口，崩溃日志写入 /etc，然后停止。</p><p>启动时的自检会故意触发 #DE、#UD 和 #PF，并断言内核能够存活 - 每次启动日志上都有 <code>exception self-test: 3/3</code>，因此有缺陷的陷阱路径永远不会到达 Shell 提示符。</p><h2 id="时间源" tabindex="-1">时间源 <a class="header-anchor" href="#时间源" aria-label="Permalink to &quot;时间源&quot;">​</a></h2><p>PIT（节拍）、HPET、ACPI PM 定时器、TSC、CMOS RTC - 每个都有一个命令（<code>timer</code>、<code>hpet</code>、<code>pmtimer</code>、<code>tsc</code>、<code>rtc</code>）以及一份在 <a href="./../drivers/">../drivers/</a> 下的点亮手册。</p>',10)])])}const u=a(o,[["render",d]]);export{_ as __pageData,u as default};
